# Every keyword below raised "unexpected keyword argument", and concat took
# DataFrames only.
_ML = {"k": ["a", "b", "c"], "v": [1, 2, 3]}
_MR = {"k": ["a", "b", "d"], "v": [10, 20, 40], "w": [0.5, 1.5, 2.5]}
