def _temporal_result(r: Any) -> Any:
    if hasattr(r, "dtype") and hasattr(r, "tolist"):
        return (str(r.dtype), [str(v) for v in r.tolist()], [str(v) for v in r.index])
    return (type(r).__name__, str(r))


